def merge_intervals(intervals):
    if not intervals:
        return []
    sorted_intervals = sorted(intervals, key=lambda x: (x[0], x[1]))
    merged = [list(sorted_intervals[0])]
    for current in sorted_intervals[1:]:
        prev = merged[-1]
        if current[0] <= prev[1]:
            prev[1] = max(prev[1], current[1])
        else:
            merged.append(list(current))
    return merged

import heapq


def toposort(nodes, edges):
    adj = {node: set() for node in nodes}
    in_degree = {node: 0 for node in nodes}

    for src, dst in edges:
        if dst in adj and src in adj and dst not in adj[src]:
            adj[src].add(dst)
            in_degree[dst] += 1

    heap = [node for node in nodes if in_degree[node] == 0]
    heapq.heapify(heap)

    result = []
    while heap:
        node = heapq.heappop(heap)
        result.append(node)
        for neighbor in adj[node]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                heapq.heappush(heap, neighbor)

    if len(result) != len(nodes):
        raise ValueError("Cycle detected in graph")

    return result

def stable_batches(items, limit):
    if limit <= 0:
        raise ValueError("limit must be positive")
    for name, weight in items:
        if weight <= 0 or weight > limit:
            raise ValueError("invalid weight")
    if not items:
        return []
    batches = []
    current_batch = []
    current_weight = 0
    for name, weight in items:
        if current_weight + weight > limit:
            batches.append(current_batch)
            current_batch = [name]
            current_weight = weight
        else:
            current_batch.append(name)
            current_weight += weight
    if current_batch:
        batches.append(current_batch)
    return batches

def parse_env(text):
    import re
    result = {}
    key_re = re.compile(r'\A[A-Za-z_][A-Za-z0-9_]*\Z')
    for raw in text.splitlines():
        line = raw.strip()
        if not line or line.startswith('#'):
            continue
        if '=' not in line:
            raise ValueError(f"invalid environment assignment: {line!r}")
        key, _, value = line.partition('=')
        key = key.strip()
        value = value.strip()
        if not key_re.match(key):
            raise ValueError(f"invalid environment variable name: {key!r}")
        if (len(value) >= 2 and value[0] == '"' and value[-1] == '"') or \
           (len(value) >= 2 and value[0] == "'" and value[-1] == "'"):
            value = value[1:-1]
        result[key] = value
    return result

def fifo_admit(active, queued, budget, slots):
    if any(q > budget for q in queued):
        raise ValueError("a queued reservation exceeds the whole budget")

    admitted = []
    used_tokens = sum(active)
    used_slots = len(active)

    for q in queued:
        if used_slots + 1 > slots or used_tokens + q > budget:
            break
        admitted.append(q)
        used_tokens += q
        used_slots += 1

    return admitted, queued[len(admitted):]
